package com.dy.artisan3d.ui.screen.main.settingsimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Contactsimport androidx.compose.material.icons.filled.Infoimport androidx.compose.material.icons.filled.Languageimport androidx.compose.material.icons.filled.Publicimport androidx.compose.material.icons.filled.Settingsimport androidx.compose.material3.Scaffoldimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.app_nameimport artisan3d.composeapp.generated.resources.choose_languageimport com.dy.artisan3d.navigation.Screenimport com.dy.artisan3d.ui.component.ArtisanSettingItemimport com.dy.artisan3d.ui.component.Topbarimport com.dy.artisan3d.util.openExternalUrlimport org.jetbrains.compose.resources.stringResource@Composablefun InfoContent(    onNextScreen: (Any)-> Unit) {    val items = listOf(        ArtisanMenuItem(            icon = Icons.Default.Info,            title = Res.string.app_name,            action = ArtisanMenuAction.None        ),        ArtisanMenuItem(            icon = Icons.Default.Contacts,            title = Res.string.app_name,            action = ArtisanMenuAction.None        ),        ArtisanMenuItem(            icon = Icons.Default.Settings,            title = Res.string.choose_language,            action = ArtisanMenuAction.Navigate(Screen.Settings)        ),        ArtisanMenuItem(            icon = Icons.Default.Public,            title = Res.string.app_name,            action = ArtisanMenuAction.OpenUrl("https://etnotravel.uz")        )    )    Scaffold(        topBar = {            Topbar(title = stringResource(Res.string.app_name))        }    ) { paddingValues ->        LazyColumn(            modifier = Modifier.padding(paddingValues).fillMaxSize(),            verticalArrangement = Arrangement.Center,            contentPadding = PaddingValues(start = 12.dp, end = 12.dp, bottom = 90.dp,top=12.dp)        ) {            items(items) { item ->                ArtisanSettingItem(                    artisanMenuItem = item,                    onClick = {                        when (item.action) {                            is ArtisanMenuAction.Execute -> {}                            is ArtisanMenuAction.Navigate -> {                                onNextScreen(item.action.screen)                            }                            is ArtisanMenuAction.None -> {}                            is ArtisanMenuAction.OpenUrl -> {                                openExternalUrl(item.action.url)                            }                        }                    })            }        }    }}